/**
 * ILANEL POC — Ross Gardam clone
 *
 * Values taken from rossgardam.com.au's live stylesheet, not estimated:
 *   .article__content p  font-size 1.8rem / weight 300 / line-height 1.35
 *   .article__head       margin-bottom 4.1rem
 *   .section-details     padding 0 0 18rem
 *   .shell               padding 0 3rem (mobile 2rem)
 *   letter-spacing       .005 / .01 / .02 / .06 / .08em
 *   body                 #fff bg, #000 text, ABCFavorit
 *   font-weights         300 / 400 / 600 only
 *
 * RG use ABCFavorit (grotesque) + Lyon Display (serif wordmark and
 * product names). Both are licensed and cannot be redistributed, so this
 * substitutes Inter and a Didone serif. Swap in the licensed faces for
 * production and the match tightens further.
 *
 * RG set html{font-size:62.5%} so 1rem = 10px. We do the same, which is
 * why the values above transfer directly.
 */

html {
  font-size: 62.5%;
}

:root {
  --rg-ink: #000;
  --rg-bg: #fff;
  --rg-tile: #eee;
  --rg-tile-alt: #f4f4f4;
  --rg-rule: #d5d5d5;
  --rg-muted: #767676;
  --rg-accent: #8a6d3b;

  --rg-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;
  --rg-serif: 'Playfair Display', 'Times New Roman', serif;

  --rg-shell: 3rem;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--rg-bg);
  color: var(--rg-ink);
  font-family: var(--rg-sans);
  font-weight: 400;
  font-size: 1.5rem;
  line-height: 1.5;
  text-align: left;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.rg-shell {
  max-width: 168rem;
  margin: 0 auto;
  padding: 0 var(--rg-shell);
}

/* --- Header --------------------------------------------------------------- */

.rg-header {
  padding: 3.2rem 0 2.8rem;
}

.rg-header__inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  padding: 0 var(--rg-shell);
}

.rg-navbtn {
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0.5rem;
  width: 2.4rem;
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
}

.rg-navbtn span {
  display: block;
  height: 1px;
  background: var(--rg-ink);
}

.rg-navbtn span:nth-child(2) {
  width: 70%;
}

.rg-header__logo {
  grid-column: 2;
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 2.9rem;
  font-weight: 400;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  line-height: 1;
  text-indent: 0.18em;
}

.rg-utilities {
  grid-column: 3;
  display: flex;
  justify-content: flex-end;
  gap: 1.8rem;
}

/* --- Hero ----------------------------------------------------------------- */

/* --- Hero carousel -------------------------------------------------------- */

/* On product pages the header sits over the hero, so the image runs to the
   very top of the page — including behind the wordmark. */
body.has-hero .rg-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 10;
  color: #fff;
}

body.has-hero .rg-navbtn span {
  background: #fff;
}

/* A soft scrim keeps the white header legible over pale photography. */
body.has-hero .rg-header::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0, 0, 0, 0.35), rgba(0, 0, 0, 0));
  pointer-events: none;
  z-index: -1;
}

/* Sized in vh so it fills the top of the viewport without swallowing the
   page. Capped so tall desktop windows don't stretch it absurdly. */
.rg-hero {
  position: relative;
  width: 100%;
  height: 82vh;
  max-height: 84rem;
  min-height: 48rem;
  background-color: var(--rg-tile);
  overflow: hidden;
}

.rg-hero__slide {
  position: absolute;
  inset: 0;
  background-position: center;
  background-size: cover;
  background-repeat: no-repeat;
  opacity: 0;
  transition: opacity 1.1s ease;
}

.rg-hero__slide.is-active {
  opacity: 1;
}

.rg-hero__nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  z-index: 3;
  width: 5rem;
  height: 5rem;
  border: 0;
  background: none;
  color: #fff;
  font-size: 3.2rem;
  line-height: 1;
  cursor: pointer;
  opacity: 0.75;
  transition: opacity 0.2s ease;
}

.rg-hero__nav:hover {
  opacity: 1;
}

.rg-hero__nav--prev {
  left: 1rem;
}

.rg-hero__nav--next {
  right: 1rem;
}

.rg-hero__dots {
  position: absolute;
  bottom: 3rem;
  left: 0;
  right: 0;
  z-index: 3;
  display: flex;
  justify-content: center;
  gap: 1rem;
}

.rg-hero__dot {
  width: 4rem;
  height: 2px;
  padding: 0;
  border: 0;
  background: rgba(255, 255, 255, 0.45);
  cursor: pointer;
  transition: background 0.25s ease;
}

.rg-hero__dot.is-active {
  background: #fff;
}

/* --- Breadcrumbs ---------------------------------------------------------- */

.rg-breadcrumbs {
  padding: 2.6rem 0;
}

.rg-breadcrumbs--inline {
  padding: 0 0 3.5rem;
}

.ilanel-breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1.1rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.ilanel-breadcrumbs li + li::before {
  content: '/';
  margin-right: 0.9rem;
}

.ilanel-breadcrumbs a:hover {
  color: var(--rg-ink);
}

.ilanel-breadcrumbs [aria-current='page'] {
  color: var(--rg-ink);
}

/* --- Product article ------------------------------------------------------ */

.rg-main {
  padding-bottom: 2rem;
}

/* .rg-article shares an element with .rg-shell, so it must not reset the
   horizontal padding — doing so clipped the product name off the page. */
.rg-article {
  padding-top: 4.5rem;
  padding-bottom: 4.5rem;
}

.rg-article__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr);
  gap: 8rem;
  align-items: start;
}

.rg-article__head {
  margin-bottom: 2.5rem;
}

/* The piece name: large, light serif — RG's signature move. */
.rg-product__name {
  margin: 0 0 1rem;
  font-family: var(--rg-serif);
  font-size: 5.6rem;
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: 0.01em;
}

.rg-product__type {
  margin: 0;
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-article__content p {
  max-width: 60rem;
  margin: 0 0 2.2rem;
  font-size: 1.8rem;
  font-weight: 300;
  line-height: 1.35;
}

.rg-meta {
  display: flex;
  gap: 1.5rem;
  margin: 0 0 0.7rem;
  font-size: 1.3rem;
  font-weight: 300;
}

.rg-meta__label {
  min-width: 9rem;
  font-size: 1.1rem;
  font-weight: 400;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

/* RG's link style: uppercase, tracked, trailing slash, underline on hover. */
.rg-cta {
  margin: 3.5rem 0 0;
}

.rg-link {
  display: inline-block;
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  border-bottom: 1px solid transparent;
  padding-bottom: 0.3rem;
  transition: border-color 0.2s ease;
}

.rg-link:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Storytelling --------------------------------------------------------- */

.rg-story {
  padding: 1rem 0 2rem;
}

.rg-article__row--middle {
  align-items: center;
}

/* RG alternate the media side; --reversed puts copy first. */
.rg-article--reversed .rg-article__row {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.35fr);
}

.rg-feature img {
  width: 100%;
  background: var(--rg-tile);
}

/* ILANEL's scene photography is wide; a 4:5 portrait crop cut the fixture
   out of frame entirely. 5:4 keeps the piece visible. */
.rg-feature--portrait img {
  aspect-ratio: 5 / 4;
  object-fit: cover;
}

.rg-feature--landscape img {
  aspect-ratio: 3 / 2;
  object-fit: cover;
}

.rg-story__title {
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 3.2rem;
  font-weight: 400;
  line-height: 1.15;
}

/* --- Configurator --------------------------------------------------------- */

.rg-configure {
  padding: 6rem 0;
  background: var(--rg-tile-alt);
  margin-top: 2rem;
}

.rg-configure__inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 6rem;
  align-items: start;
}

.rg-configure__preview {
  background: #fff;
  aspect-ratio: 895 / 1023;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.rg-configure__preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: opacity 0.3s ease;
}

.rg-configure__head {
  margin-bottom: 3rem;
}

.rg-configure__eyebrow {
  margin: 0 0 0.6rem;
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-configure__title {
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 3.6rem;
  font-weight: 400;
  line-height: 1.1;
}

.rg-configure__title span {
  display: block;
  margin-top: 0.5rem;
  font-family: var(--rg-sans);
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-config__group {
  margin: 0 0 3rem;
  padding: 2rem 0 0;
  border: 0;
  border-top: 1px solid var(--rg-rule);
}

.rg-config__label {
  display: block;
  margin-bottom: 1.4rem;
  padding: 0;
  font-size: 1.1rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-config__options {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.rg-config__pill input,
.rg-config__swatch input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.rg-config__pill span {
  display: inline-block;
  padding: 0.9rem 2rem;
  border: 1px solid var(--rg-rule);
  font-size: 1.2rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  cursor: pointer;
  transition: border-color 0.2s ease, background 0.2s ease, color 0.2s ease;
}

.rg-config__pill:hover span {
  border-color: var(--rg-ink);
}

.rg-config__pill input:checked + span {
  background: var(--rg-ink);
  border-color: var(--rg-ink);
  color: #fff;
}

.rg-config__options--swatches {
  gap: 1.6rem;
}

.rg-config__swatch {
  width: 8rem;
  cursor: pointer;
}

.rg-config__swatch-media {
  display: block;
  aspect-ratio: 1 / 1;
  overflow: hidden;
  border: 1px solid transparent;
  outline: 1px solid var(--rg-rule);
  outline-offset: -1px;
  transition: outline-color 0.2s ease;
}

.rg-config__swatch-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.rg-config__swatch input:checked + .rg-config__swatch-media {
  outline: 2px solid var(--rg-ink);
  outline-offset: 2px;
}

.rg-config__swatch-name {
  display: block;
  margin-top: 0.8rem;
  font-size: 1rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-config__summary {
  margin: 3rem 0;
  padding-top: 2rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-config__summary p {
  display: flex;
  gap: 1.5rem;
  align-items: baseline;
  margin: 0 0 0.8rem;
  font-size: 1.4rem;
  font-weight: 300;
}

.rg-config__summary .rg-config__label {
  min-width: 11rem;
  margin: 0;
}

.rg-config__price .js-config-price {
  font-size: 2rem;
  font-weight: 400;
}

/* Stacked, full-width — RG present the actions as a vertical list, and it
   reads as a clear priority order rather than three competing pills. */
.rg-config__actions {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 2rem;
  max-width: 34rem;
}

.rg-config__actions .rg-btn {
  width: 100%;
  text-align: center;
}

.rg-btn {
  display: inline-block;
  padding: 1.3rem 3.4rem;
  border: 1px solid var(--rg-ink);
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
}

.rg-btn:hover {
  background: var(--rg-ink);
  color: #fff;
}

.rg-btn--solid {
  background: var(--rg-ink);
  color: #fff;
}

.rg-btn--solid:hover {
  background: transparent;
  color: var(--rg-ink);
}

.rg-config__download {
  margin: 0;
}

/* --- Sections (Finishes, Downloads) --------------------------------------- */

.rg-section {
  padding: 4rem 0;
}

.rg-section--details {
  padding-bottom: 5rem;
}

.rg-section__label {
  display: block;
  margin-bottom: 2.5rem;
  font-size: 1.2rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 4rem 8rem;
  padding-top: 2.5rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-section__title {
  max-width: 38rem;
  margin: 0;
  font-size: 2.2rem;
  font-weight: 300;
  line-height: 1.3;
  letter-spacing: 0.005em;
}

.rg-section__list {
  margin: 0;
  padding: 0;
  list-style: none;
  columns: 2;
  column-gap: 4rem;
}

.rg-section__list li {
  margin-bottom: 1.4rem;
  font-size: 1.4rem;
  font-weight: 300;
  break-inside: avoid;
}

.rg-section__list--links li {
  font-size: 1.2rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-section__list--links a {
  border-bottom: 1px solid var(--rg-rule);
  padding-bottom: 0.3rem;
  transition: border-color 0.2s ease;
}

.rg-section__list--links a:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Range archive -------------------------------------------------------- */

.rg-main--archive {
  padding-top: 1rem;
}

.rg-range__header {
  margin-bottom: 4.5rem;
}

.rg-range__title {
  margin: 0 0 1.2rem;
  font-family: var(--rg-serif);
  font-size: 4.4rem;
  font-weight: 400;
  line-height: 1.1;
}

.rg-range__intro {
  max-width: 52rem;
}

.rg-range__intro p {
  margin: 0;
  font-size: 1.6rem;
  font-weight: 300;
  line-height: 1.4;
  color: #333;
}

/* Filters: accent label, hairline rule, wide-spaced terms. */
.rg-filters {
  margin-bottom: 4.5rem;
}

.rg-filters__label {
  display: block;
  margin-bottom: 1.2rem;
  padding-bottom: 1.2rem;
  border-bottom: 1px solid var(--rg-ink);
  font-size: 1.1rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-filters ul {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 6rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.rg-filters a {
  font-size: 1.3rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  transition: opacity 0.18s ease;
}

.rg-filters a:hover {
  opacity: 0.5;
}

.rg-filters .is-current a {
  font-weight: 600;
}

/* --- Product grid --------------------------------------------------------- */

.rg-products {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 4rem 3rem;
  margin: 0 0 4rem;
  padding: 0;
  list-style: none;
}

/* RG serve product tiles at 895x1023 — a portrait crop, not a square. */
.rg-product-card__media {
  background: var(--rg-tile);
  aspect-ratio: 895 / 1023;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.6rem;
  overflow: hidden;
}

.rg-products li:nth-child(3n + 2) .rg-product-card__media {
  background: var(--rg-tile-alt);
}

/* ILANEL's photography is in-situ interiors, not RG's cut-out product
   shots on white. `cover` fills the tile cleanly instead of leaving a
   landscape image floating in grey. Swap to `contain` with padding once
   the studio supplies cut-outs. */
.rg-product-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.5s ease, opacity 0.3s ease;
}

.rg-product-card a:hover .rg-product-card__media img {
  transform: scale(1.03);
  opacity: 0.9;
}

.rg-product-card__title {
  margin: 0 0 0.3rem;
  font-size: 1.3rem;
  font-weight: 400;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-product-card__type {
  margin: 0 0 0.4rem;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-product-card__price {
  margin: 0;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-product-card__price .woocommerce-Price-amount {
  font-weight: 300;
}

/* --- Discover More -------------------------------------------------------- */

.rg-discover {
  padding: 5rem 0 4rem;
}

.rg-discover__title {
  margin: 0 0 3.5rem;
  font-family: var(--rg-serif);
  font-size: 3.2rem;
  font-weight: 400;
  text-align: center;
}

/* RG centre the copy under discover cards. */
.rg-products--discover {
  margin-bottom: 3rem;
}

.rg-products--discover .rg-product-card__title,
.rg-products--discover .rg-product-card__type,
.rg-products--discover .rg-product-card__price {
  text-align: center;
}

.rg-discover__cta {
  margin: 0;
  text-align: center;
}

/* --- Share row ------------------------------------------------------------ */

.rg-share {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-share .rg-config__label {
  min-width: 11rem;
  margin: 0;
}

.rg-share a {
  font-size: 1.2rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s ease;
}

.rg-share a:hover {
  border-bottom-color: var(--rg-ink);
}

/* --- Lit / unlit toggle --------------------------------------------------- */

.rg-configure__preview {
  position: relative;
}

.rg-lightswitch {
  position: absolute;
  bottom: 1.6rem;
  left: 1.6rem;
  display: flex;
  align-items: center;
  gap: 0.8rem;
  padding: 0.8rem 1.6rem;
  border: 1px solid rgba(0, 0, 0, 0.12);
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(6px);
  font-size: 1rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: background 0.25s ease, border-color 0.25s ease;
}

.rg-lightswitch:hover {
  border-color: rgba(0, 0, 0, 0.35);
}

.rg-lightswitch__dot {
  width: 0.9rem;
  height: 0.9rem;
  border-radius: 50%;
  background: #e8c37a;
  box-shadow: 0 0 0.7rem 0.15rem rgba(232, 195, 122, 0.9);
  transition: background 0.35s ease, box-shadow 0.35s ease;
}

/* Unlit: cool the image down and kill the glow. */
.rg-configure__preview.is-unlit img {
  filter: brightness(0.62) saturate(0.75) contrast(1.05);
}

.rg-configure__preview.is-unlit .rg-lightswitch__dot {
  background: #b9b9b9;
  box-shadow: none;
}

.rg-configure__preview img {
  transition: filter 0.6s ease;
}

/* --- Reveal on scroll ----------------------------------------------------- */

.rg-reveal {
  opacity: 0;
  transform: translateY(1.8rem);
  transition: opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1),
    transform 0.8s cubic-bezier(0.16, 1, 0.3, 1);
}

.rg-reveal.is-visible {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .rg-reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

/* --- Header state --------------------------------------------------------- */

body.has-hero .rg-header {
  transition: background 0.35s ease, color 0.35s ease;
}

/* Once past the hero the header flips to dark-on-white and pins. */
body.has-hero.is-past-hero .rg-header {
  position: fixed;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(10px);
  color: var(--rg-ink);
  border-bottom: 1px solid var(--rg-rule);
}

body.has-hero.is-past-hero .rg-header::before {
  opacity: 0;
}

body.has-hero.is-past-hero .rg-navbtn span {
  background: var(--rg-ink);
}

/* --- Sticky enquiry bar --------------------------------------------------- */

.rg-stickybar {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  padding: 1.4rem 0;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(10px);
  border-top: 1px solid var(--rg-rule);
  transform: translateY(110%);
  transition: transform 0.45s cubic-bezier(0.16, 1, 0.3, 1);
}

.rg-stickybar.is-visible {
  transform: none;
}

.rg-stickybar__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}

.rg-stickybar__meta {
  display: flex;
  align-items: baseline;
  gap: 1.6rem;
}

.rg-stickybar__name {
  font-size: 1.3rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.rg-stickybar__price {
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-stickybar__actions {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.rg-btn--small {
  padding: 0.9rem 2.4rem;
}

.rg-btn--quiet {
  border-color: var(--rg-rule);
  color: var(--rg-muted);
}

.rg-btn--quiet:hover {
  border-color: var(--rg-ink);
  background: transparent;
  color: var(--rg-ink);
}

/* --- Footer --------------------------------------------------------------- */

.rg-footer {
  padding: 5rem 0 3rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-footer__inner {
  display: grid;
  gap: 4rem;
}

/* RG put the studio identity and address in a left-hand column BESIDE the
   nav columns, not stacked above them. */
.rg-footer__content {
  display: grid;
  grid-template-columns: 26rem minmax(0, 1fr);
  gap: 4rem 6rem;
  align-items: start;
}

.rg-footer__identity {
  display: grid;
  gap: 2.4rem;
  align-content: start;
}

.rg-footer__logo {
  margin: 0;
  font-family: var(--rg-serif);
  font-size: 2.4rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.rg-footer__address {
  display: grid;
  gap: 0.2rem;
  font-style: normal;
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-footer__address a:hover {
  color: var(--rg-ink);
}

.rg-footer__spacer {
  margin-top: 1.2rem;
}

.rg-footer__navbar {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 3rem;
}

.rg-footer__navtitle {
  margin: 0 0 1.8rem;
  font-size: 1.1rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--rg-accent);
}

.rg-footer__nav ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.rg-footer__nav li {
  margin-bottom: 1rem;
}

.rg-footer__nav a {
  font-size: 1.1rem;
  font-weight: 300;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--rg-muted);
  transition: color 0.2s ease;
}

.rg-footer__nav a:hover {
  color: var(--rg-ink);
}

.rg-footer__inline {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr);
  gap: 3rem;
  padding-top: 3rem;
  border-top: 1px solid var(--rg-rule);
}

.rg-footer__acknowledgement {
  max-width: 62ch;
  margin: 0;
  font-size: 1.1rem;
  font-weight: 300;
  line-height: 1.6;
  color: var(--rg-muted);
}

.rg-footer__legal {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.5rem 2rem;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 1rem;
  font-weight: 300;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--rg-muted);
}

.rg-footer__legal a:hover {
  color: var(--rg-ink);
}

/* --- Responsive ----------------------------------------------------------- */

@media (max-width: 1100px) {
  .rg-article__row,
  .rg-article--reversed .rg-article__row {
    grid-template-columns: 1fr;
    gap: 3.5rem;
  }

  /* Keep the image below the copy on reversed rows when stacked. */
  .rg-article--reversed .rg-article__col--media {
    order: 2;
  }

  .rg-configure__inner {
    grid-template-columns: 1fr;
    gap: 4rem;
  }

  .rg-hero {
    height: 70vh;
  }

  .rg-products {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .rg-product__name {
    font-size: 4.4rem;
  }
}

@media (max-width: 900px) {
  .rg-footer__content,
  .rg-footer__inline {
    grid-template-columns: 1fr;
    gap: 2rem;
  }

  .rg-footer__navbar {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 2.5rem;
  }

  .rg-footer__legal {
    justify-content: flex-start;
  }

  .rg-stickybar__inner {
    gap: 1rem;
  }

  .rg-stickybar__meta {
    flex-direction: column;
    gap: 0.2rem;
  }
}

@media (max-width: 760px) {
  .rg-grid {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .rg-section__list {
    columns: 1;
  }

  .rg-hero {
    height: 52vh;
    min-height: 30rem;
  }

  .rg-header__logo {
    font-size: 2.2rem;
  }
}

@media (max-width: 374px) {
  :root {
    --rg-shell: 2rem;
  }

  .rg-products {
    grid-template-columns: 1fr;
  }
}

/**
 * Hero carousel + configurator.
 *
 * Vanilla, no dependencies — the Playground sandbox blocks external
 * scripts and the behaviour is simple enough not to need a library.
 */
(function () {
  'use strict';

  /* --- Hero carousel: cross-fade, matching RG's .slider--fade --------- */

  function initHero() {
    var hero = document.querySelector('.js-hero');
    if (!hero) return;

    var slides = hero.querySelectorAll('.rg-hero__slide');
    if (slides.length < 2) return;

    var dots = hero.querySelectorAll('.rg-hero__dot');
    var index = 0;
    var timer = null;

    function show(next) {
      index = (next + slides.length) % slides.length;

      slides.forEach(function (slide, i) {
        slide.classList.toggle('is-active', i === index);
      });

      dots.forEach(function (dot, i) {
        dot.classList.toggle('is-active', i === index);
      });
    }

    function advance() {
      show(index + 1);
    }

    function restart() {
      window.clearInterval(timer);
      timer = window.setInterval(advance, 6000);
    }

    hero.querySelector('.js-hero-next').addEventListener('click', function () {
      show(index + 1);
      restart();
    });

    hero.querySelector('.js-hero-prev').addEventListener('click', function () {
      show(index - 1);
      restart();
    });

    dots.forEach(function (dot) {
      dot.addEventListener('click', function () {
        show(parseInt(dot.dataset.index, 10));
        restart();
      });
    });

    restart();
  }

  /* --- Configurator: swap preview, update summary and price ----------- */

  function initConfigurator() {
    var form = document.querySelector('.rg-config');
    if (!form) return;

    var preview = document.querySelector('.js-config-image');
    var summary = form.querySelector('.js-config-summary');
    var priceEl = form.querySelector('.js-config-price');
    var base = parseFloat(form.dataset.basePrice || '0');

    // Read the currency symbol off the server-rendered price so we don't
    // hardcode it — Woo may be configured for any currency.
    var rendered = priceEl ? priceEl.textContent.trim() : '';
    var symbol = (rendered.match(/^[^\d]*/) || [''])[0] || '$';

    function money(value) {
      return (
        symbol +
        value.toLocaleString(undefined, {
          minimumFractionDigits: 2,
          maximumFractionDigits: 2,
        })
      );
    }

    function update() {
      var length = form.querySelector('input[name="ilanel_length"]:checked');
      var finish = form.querySelector('input[name="ilanel_finish"]:checked');

      if (finish && preview && finish.dataset.image) {
        preview.src = finish.dataset.image;
      }

      var parts = [];
      if (length) parts.push(length.value);
      if (finish) parts.push(finish.value);
      if (summary) summary.textContent = parts.join(' · ');

      if (priceEl) {
        var increment = length ? parseFloat(length.dataset.increment || '0') : 0;
        priceEl.textContent = money(base + increment);
      }
    }

    form.addEventListener('change', update);
    update();
  }

  /* --- Lit / unlit toggle -------------------------------------------- */

  function initLightSwitch() {
    var btn = document.querySelector('.js-lightswitch');
    var preview = document.querySelector('.rg-configure__preview');
    if (!btn || !preview) return;

    var label = btn.querySelector('.rg-lightswitch__text');
    var lit = true;

    btn.addEventListener('click', function () {
      lit = !lit;
      preview.classList.toggle('is-unlit', !lit);
      btn.setAttribute('aria-pressed', String(lit));
      if (label) label.textContent = lit ? 'Lit' : 'Unlit';
    });
  }

  /* --- Reveal on scroll ------------------------------------------------
   * Sections fade and rise slightly as they enter the viewport. Kept
   * subtle — a few hundred ms, small travel. Respects
   * prefers-reduced-motion by simply not running.
   */

  function initReveal() {
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    if (!('IntersectionObserver' in window)) return;

    var targets = document.querySelectorAll(
      '.rg-article__col, .rg-feature, .rg-section, .rg-product-card, .rg-configure__panel, .rg-configure__preview'
    );

    targets.forEach(function (el) {
      el.classList.add('rg-reveal');
    });

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          if (!entry.isIntersecting) return;
          entry.target.classList.add('is-visible');
          io.unobserve(entry.target);
        });
      },
      { rootMargin: '0px 0px -10% 0px', threshold: 0.08 }
    );

    targets.forEach(function (el) {
      io.observe(el);
    });
  }

  /* --- Sticky enquiry bar ----------------------------------------------
   * Appears once the configurator scrolls out of view, so the call to
   * action is never more than a tap away on a long page.
   */

  function initStickyBar() {
    var config = document.getElementById('configure');
    var bar = document.querySelector('.js-stickybar');
    if (!config || !bar) return;

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          // Show only once the configurator has been scrolled past.
          var past = !entry.isIntersecting && entry.boundingClientRect.top < 0;
          bar.classList.toggle('is-visible', past);
        });
      },
      { threshold: 0 }
    );

    io.observe(config);
  }

  /* --- Header state on scroll ------------------------------------------
   * Over the hero the header is white on photography; once past it, it
   * needs to flip to dark on white.
   */

  function initHeaderState() {
    var hero = document.querySelector('.rg-hero');
    if (!hero || !document.body.classList.contains('has-hero')) return;

    var io = new IntersectionObserver(
      function (entries) {
        entries.forEach(function (entry) {
          document.body.classList.toggle('is-past-hero', !entry.isIntersecting);
        });
      },
      { threshold: 0, rootMargin: '-80px 0px 0px 0px' }
    );

    io.observe(hero);
  }

  function init() {
    initHero();
    initConfigurator();
    initLightSwitch();
    initReveal();
    initStickyBar();
    initHeaderState();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
